var bytes = require('..');

describe('proof', function () {
  it('parse() must not extract a unit from a string that does not start with a number', function () {
    // The unit regexp is anchored (^...$), so a leading space makes the
    // match fail and parse() falls back to parseInt() over the whole
    // string, i.e. the value is treated as plain bytes. With an
    // unanchored regexp the trailing "1kb" is extracted and turned
    // into 1024 instead.
    assert.strictEqual(bytes.parse(' 1kb'), 1);
    assert.strictEqual(bytes.parse(' 1.5 kb'), 1);
  });
});
"}, "note": "The '^' anchor was removed from parseRegExp, so parse() now extracts a size/unit pair from anywhere in the string. Inputs like ' 1kb' that previously failed the match and returned parseInt(' 1kb') = 1 now return 1024 (and strings like 'foo 1kb' return 1024 instead of null), which is caller-observable."}
```

